  __imgHeaders(pageUrl) { return { Referer: (this.__origin(pageUrl) || this.__base()) + '/', 'User-Agent': __VB.UA, Accept: 'image/avif,image/webp,image/apng,image/*,*/*;q=0.8' }; }
